        body: `Πολλοί αιθουσαίοι ασθενείς αρχίζουν να φοβούνται τις κινήσεις που προκαλούν συμπτώματα και σταδιακά περιορίζουν τη ζωή τους στις λίγες θέσεις που νιώθουν ασφαλείς. Το σύστημα, στερημένο από την είσοδο που χρειάζεται για να επαναβαθμονομηθεί, γίνεται πιο ευαίσθητο και όχι λιγότερο. Η εκπαίδευση εξοικείωσης αντιστρέφει αυτή την πορεία. Μια σύντομη λίστα προσεκτικά επιλεγμένων, εξατομικευμένα δοσολογημένων κινήσεων που προκαλούν ήπια τη ζάλη του ασθενούς επαναλαμβάνεται αρκετές φορές την ημέρα. Η δόση ρυθμίζεται έτσι ώστε τα συμπτώματα να εμφανίζονται αλλά να υποχωρούν εντός ενός λεπτού. Σε δύο έως έξι εβδομάδες ο εγκέφαλος επανακατατάσσει αυτές τις κινήσεις ως ασφαλείς και η αντίδραση ζάλης συρρικνώνεται. Αυτή είναι η πιο σημαντική φάση για τον ασθενή με επίμονη στασική-αντιληπτική ζάλη ή υπερευαισθησία στην οπτική κίνηση.`,
