        body: `Η αιθουσαία αποκατάσταση δεν τελειώνει σε ένα ήσυχο δωμάτιο θεραπείας. Τα πραγματικά περιβάλλοντα — πεζοδρόμια με ανώμαλες πλάκες, διάδρομοι σούπερ μάρκετ, κυλιόμενες σκάλες, ημίφως εστιατορίου, νυχτερινό περπάτημα σε γρήγορο ρυθμό — είναι εκεί όπου οι αιθουσαίοι ασθενείς πέφτουν και όπου ξαναχτίζεται ή χάνεται η αυτοπεποίθηση. Η μεταγενέστερη φάση της θεραπείας εκθέτει σκόπιμα τον ασθενή σε δυσκολότερες επιφάνειες, στενότερες βάσεις στήριξης, κινήσεις κεφαλιού και ματιών κατά τη βάδιση και βαθμιαία εργασία διπλού καθήκοντος (περπάτημα ενώ μετράει, στρίβοντας το κεφάλι, κρατώντας τσάντα). Ειδικά για τους ηλικιωμένους ασθενείς, αυτό το μέρος του προγράμματος είναι που γεφυρώνει την απόσταση μεταξύ «λιγότερη ζάλη» και «πίσω στην κανονική ζωή».`,
