        body: `Η απεικόνιση συχνά σοκάρει τους ασθενείς. Λέξεις όπως «κήλη», «προβολή», «έξωση» ή «πίεση νευρικού ριζίου» ακούγονται μόνιμες. Δεν είναι. Το υλικό του δίσκου είναι βιολογικός ιστός. Το σώμα αναγνωρίζει ένα κηλιδωμένο τμήμα ως κάτι που πρέπει να αποβληθεί και, σε διάστημα εβδομάδων έως μηνών, αυτό συρρικνώνεται, αφυδατώνεται και απορροφάται μερικώς. Η φλεγμονή γύρω από το νευρικό ρίζιο υποχωρεί. Το νεύρο, που είναι αξιοσημείωτα ανθεκτικό, ανακτά τη λειτουργία του. Πόνος που μοιάζει αδιαχείριστος στη δεύτερη εβδομάδα συχνά είναι ανάμνηση μέχρι τον τρίτο μήνα.

Αυτό που δεν μπορεί να δείξει μια μαγνητική είναι πώς κινείται, φορτίζεται και αναρρώνει η σπονδυλική στήλη ενός συγκεκριμένου ανθρώπου — που είναι ακριβώς αυτό που καθορίζει την πορεία. Δύο ασθενείς με την ίδια εικόνα μπορεί να έχουν πολύ διαφορετική έκβαση, και η διαφορά σπάνια είναι χειρουργική. Είναι η ποιότητα της συντηρητικής αντιμετώπισης, η συνέπεια στην κίνηση και ο σωστός χειρισμός των πρώτων εβδομάδων που την κρίνουν.`,
