        body: `Η φάση της λειτουργικής επαναφόρτισης είναι εκεί όπου οι περισσότεροι ασθενείς σιωπηλά σταματούν να εξελίσσονται, γιατί αποφεύγουν ακριβώς τις κινήσεις που πρέπει να ξαναμάθουν. Η κάμψη μπροστά, η άρση από το έδαφος, το παρατεταμένο κάθισμα — όλα αυτά μοιάζουν επικίνδυνα για μήνες μετά από μια κήλη. Η σωστή προσέγγιση δεν είναι να αποφεύγονται αλλά να επανεισάγονται, σκόπιμα και σταδιακά, σε ελεγχόμενο περιβάλλον. Hinges με μπαστούνι, kettlebell deadlifts σε ελαφρά φορτία, ρυθμισμένη εργασία ανοχής στο κάθισμα και ασκήσεις προσαρμοσμένες στην εργασία (κηπουρική, άρση παιδιού, παρατεταμένη οδήγηση) γεφυρώνουν την απόσταση μεταξύ του «χωρίς πόνο σε ηρεμία» και του «χωρίς φόβο στην κανονική ζωή». Είναι η φάση που καθορίζει περισσότερο τη μακροχρόνια έκβαση.`,
