        heading: `Το Πλεονέκτημα της Νευροπλαστικότητας`,
        body: `Ο ανθρώπινος εγκέφαλος, ακόμη και με Πάρκινσον, παραμένει ικανός για νευροπλαστικότητα — τη δυνατότητα να σχηματίζει νέες συνδέσεις και να ενισχύει τις υπάρχουσες. Η σύγχρονη νευροεπιστήμη δείχνει ότι η εντατική, συγκεκριμένη, επαναλαμβανόμενη κίνηση μπορεί πραγματικά να αλλάξει τον τρόπο που λειτουργεί ο εγκέφαλος με Πάρκινσον. Δεν μπορεί να αποκαταστήσει τα χαμένα κύτταρα ντοπαμίνης, αλλά μπορεί να βοηθήσει το υπόλοιπο δίκτυο να λειτουργεί αποδοτικότερα και να στρατολογεί εναλλακτικές οδούς.

Γι' αυτό η φράση «αν δεν το χρησιμοποιείς, το χάνεις» λαμβάνεται κυριολεκτικά στην αποκατάσταση του Πάρκινσον. Κάθε συνεδρία στοχευμένης άσκησης είναι, με πολύ πραγματική έννοια, ένα σήμα προς το νευρικό σύστημα: αυτή η κίνηση έχει σημασία — κράτα την ενεργή.`,
