        heading: `Σχετικά με τον Πόνο Στη Μέση`,
        body: `Οσφυαλγία ονομάζουμε πόνο ή δυσφορία στην περιοχή της οσφύος - της μέσης - από τους γλουτιαίους μέχρι την 12 πλευρά. Είναι συνήθης κατάσταση, αλλά σε πολλούς ανθρώπους γίνεται χρόνια, για τον λόγο αυτό κατηγοριοποιείται σε οξύ, υπο-οξύ και χρόνιο πόνο. Στην περιοχή βρίσκονται πολλοί ιστοί του ανθρώπινου σώματος και η αιτιολογία του πόνου μπορεί να μην είναι σαφής, γι βαυτό απαιτείται αξιολόγηση από Ορθοπεδικό Φυσικοθεραπευτή.`,
