        heading: `Σχετικά με την Αυχεναλγία`,
        body: `Ο πόνος στην ευρύτερη περιοχή του αυχένα, της κεφαλής και της πλάτης στο ύψος του ώμου είναι χαρακτηριστικό της Αυχεναλγίας, η οποία χαρακτηρίζεται επίσης ως Αυχενικό Σύνδρομο. Περιλαμβάνει διάφορες παθήσεις, ή καταστάσεις που προκαλούν διάφορα συμπτώματα στην περιοχή. Απαιτείται η αξιολόγηση από Ορθοπεδικό Φυσικοθεραπευτή, ώστε να γίνουν οι κατάλληλες παρεμβάσεις που θα ωφελήσουν τον ασθενή, καθώς ο κάθε ασθενής είναι διαφορετική περίπτωση.`,
