        heading: `Παθήσεις και θεραπευτικές Επιλογές`,
        body: `Ο πόνος στον αγκώνα μπορεί να προέρχεται από διάφορους ιστούς του ανθρώπινου σώματος, μυϊκές γαστέρες, τένοντες, ορογόνους θύλακες, σύνδεσμους, οστά, χόνδρους, νεύρα. Είναι όμως ενδεχόμενο να προέρχεται και από περισσότερες από μία αιτίες, οπότε μπορεί ο ασθενής να έχει συνυπάρχουσες παθολογίες. Ο Φυσικοθεραπευτής Κωνσταντίνος Δανάλης αξιολογεί τους ασθενείς, εφαρμόζοντας τις διεθνείς κατευθυντήριες οδηγίες, και εντοπίζει πιθανούς ιστούς που προκαλούν τον πόνο, ώστε να δωθεί στοχευμένη θεραπεία.`,
